// Build showtime rows from events that already have event_id
// Mode: Run Once for All Items

const out = [];

function safeStr(v) {
  return v == null ? '' : String(v).trim();
}

// Payment mapping: Hub "Payment for Entry" → free| unknown
function mapPayment(raw) {
  const s = safeStr(raw).toLowerCase();
  if (!s) return 'unknown';

  // Hub convention used by adapters:
  // "No" means FREE. Anything else is UNKNOWN in this task (even if it looks paid).
  if (s === 'no') return 'free';

  // extra safety if any source uses text markers:
  if (s.includes('bezpłat') || s.includes('bezplat') || s.includes('wstęp wolny') || s.includes('wstep wolny')) {
    return 'free';
  }

  return 'unknown';
}

for (const item of items) {
  const row = item.json;

  // event_id must already be set by "Code – compute event_id"
  const eventId = safeStr(row.event_id);
  if (!eventId) {
    // If for some reason there is no event_id, skip this row to avoid FK errors
    continue;
  }

  const dateStr     = safeStr(row.date_str || row.Date);
  const timeStrRaw  = safeStr(row.time_str || row.Time);
  const endDateStr0 = safeStr(row.end_date_str || row._EndDate || row._end_date);
  const endDateStr  = endDateStr0 || dateStr;

  const venueRaw   = safeStr(row.venue_raw || row.Venue || row.venue);
  const venueClean = venueRaw.replace(/\s+/g, ' ').trim();
  const venue      = venueClean ? venueClean : null;


  const payRaw  = row['Payment for Entry'] ?? row.payment_raw ?? row.payment;
  const payment = mapPayment(payRaw);

  // Split times by comma/semicolon, keep non-empty tokens
  let times = [];
  if (timeStrRaw) {
    times = timeStrRaw
      .split(/[;,]/)
      .map(t => safeStr(t))
      .filter(Boolean);
  }

  // Case A: single-day, timed event (Date == _EndDate, Time not empty)
  if (dateStr && times.length > 0 && endDateStr === dateStr) {
    for (const t of times) {
      out.push({
        json: {
          event_id:  eventId,
          date:      dateStr,
          time:      t,
          _end_date: dateStr,
          venue,
          payment,
        },
      });
    }
    continue;
  }

  // Case C: multi-day, no-time (Time empty, _EndDate > Date)
  if (dateStr && !timeStrRaw && endDateStr && endDateStr !== dateStr) {
    out.push({
      json: {
        event_id:  eventId,
        date:      dateStr,
        time:      null,
        _end_date: endDateStr,
        venue,
        payment,
      },
    });
    continue;
  }

  // Case B: single-day, no-time (Time empty, _EndDate == Date or empty)
  if (dateStr && !timeStrRaw) {
    out.push({
      json: {
        event_id:  eventId,
        date:      dateStr,
        time:      null,
        _end_date: dateStr,
        venue,
        payment,
      },
    });
    continue;
  }

  // Fallback: weird combinations – best effort, one row using first time token (if any)
  if (dateStr) {
    const t = times[0] || null;
    out.push({
      json: {
        event_id:  eventId,
        date:      dateStr,
        time:      t,
        _end_date: endDateStr || dateStr,
        venue,
        payment,
      },
    });
  }
}

return out;

// Summary – metrics for WF-INGEST
// Mode: Run Once for All Items

function safeNum(v, fallback = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function getFirstJson(nodeName) {
  try {
    const it = $items(nodeName);
    return it?.[0]?.json ?? null;
  } catch {
    return null;
  }
}

function getAllJson(nodeName) {
  try {
    return ($items(nodeName) || []).map(i => i.json || {});
  } catch {
    return [];
  }
}

// --- date helpers (YYYY-MM-DD) ---
function parseISODate(iso) {
  // iso: 'YYYY-MM-DD'
  if (!iso || typeof iso !== 'string') return null;
  const m = iso.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return null;
  const y = Number(m[1]);
  const mo = Number(m[2]) - 1;
  const d = Number(m[3]);
  const dt = new Date(Date.UTC(y, mo, d));
  return Number.isNaN(dt.getTime()) ? null : dt;
}

function formatISODateUTC(dt) {
  const y = dt.getUTCFullYear();
  const m = String(dt.getUTCMonth() + 1).padStart(2, '0');
  const d = String(dt.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

function addDaysISO(iso, daysToAdd) {
  const dt = parseISODate(iso);
  if (!dt) return null;
  dt.setUTCDate(dt.getUTCDate() + Number(daysToAdd || 0));
  return formatISODateUTC(dt);
}

// Lexicographic compare works for YYYY-MM-DD
function minISO(a, b) { return (!a ? b : (!b ? a : (a < b ? a : b))); }
function maxISO(a, b) { return (!a ? b : (!b ? a : (a > b ? a : b))); }

function normalizeSource(src) {
  const s = (src || '').toLowerCase().trim();
  // raw Hub values may be "zoom.lublin.pl" / "lublin.eu"
  if (s.includes('zoom')) return 'zoom';
  if (s.includes('lublin.eu') || s.includes('official')) return 'official';
  // already normalized?
  if (s === 'zoom' || s === 'official') return s;
  return s || 'unknown';
}

function getEventStartEndFromHub(ev) {
  const start = ev?.Date || ev?.date || null;
  const end = ev?._EndDate || ev?._end_date || ev?.end_date || start;
  return { start, end };
}

// -----------------------------
// 1) Config
// -----------------------------
const cfg = getFirstJson('Config – Window & Hub params1') || {};
const daysInt = Number(cfg.days);
const windowStart = cfg.date ?? null;
const windowEnd = (windowStart && Number.isFinite(daysInt))
  ? addDaysISO(windowStart, Math.max(0, daysInt - 1))
  : windowStart;

const config = {
  date: windowStart,
  window_end: windowEnd,
  period: cfg.period ?? null,
  days: cfg.days ?? null,
  pages: cfg.pages ?? null,
  limit: cfg.limit ?? null,
  include_in_progress: cfg.include_in_progress ?? null,
};

// -----------------------------
// 2) Hub telemetry (raw response)
// -----------------------------
const hubJson = getFirstJson('HTTP – Fetch Hub events1') || {};
const hub = {
  received: safeNum(hubJson.received, null),
  deduped: safeNum(hubJson.deduped, null),
  count: safeNum(hubJson.count, null),
  events_array_length: Array.isArray(hubJson.events) ? hubJson.events.length : null,
  per_source: Array.isArray(hubJson.per_source) ? hubJson.per_source : null,
  dedupe_stats: hubJson.dedupe_stats ?? null,
  version: hubJson.version ?? null,
};

// -----------------------------
// 3) Events after mapping / event_id (your pipeline view)
// -----------------------------
const eventItems = $items('Code – compute event_id1') || [];
const eventIdToSource = new Map();
const eventIdSet = new Set();
const eventsPerSource = {};

for (const it of eventItems) {
  const j = it.json || {};
  const eventId = j.event_id;
  const src = normalizeSource(j.source);

  if (eventId) {
    eventIdSet.add(eventId);
    eventIdToSource.set(eventId, src);
  }
  eventsPerSource[src] = (eventsPerSource[src] || 0) + 1;
}

// -----------------------------
// 4) Showtime rows (planned inserts)
// -----------------------------
const showtimeRows = $items('Code – build showtime rows') || [];
let showtimesTimed = 0;
let showtimesNoTime = 0;
const showtimesPerSource = {};
const showtimeKeySet = new Set();

for (const it of showtimeRows) {
  const j = it.json || {};
  const eventId = j.event_id || null;
  const src = eventIdToSource.get(eventId) || normalizeSource(j.source) || 'unknown';

  const t = j.time ?? null;
  if (t === null || t === '') showtimesNoTime++;
  else showtimesTimed++;

  showtimesPerSource[src] = (showtimesPerSource[src] || 0) + 1;

  // uniqueness check (in-workflow diagnostic)
  const k = [
    eventId ?? '∅',
    j.date ?? '∅',
    (t === null || t === '') ? '∅' : String(t),
    (j.venue === null || j.venue === '') ? '∅' : String(j.venue),
  ].join('|');
  showtimeKeySet.add(k);
}

// -----------------------------
// 5) Prune count (if your prune node returns rows like {to_prune: N})
// -----------------------------
let toPrune = null;
try {
  const pruneItems = $items('DB – Prune showtimes') || [];
  toPrune = pruneItems.reduce((acc, it) => acc + safeNum(it.json?.to_prune, 0), 0);
} catch {
  // ignore
}

// -----------------------------
// 6) SANITY: overlap counts (Hub vs DB) for the window
// -----------------------------
const sanity = {
  window_start: windowStart,
  window_end: windowEnd,
  hub_overlap_events_total: null,
  hub_overlap_events_per_source: null,
  db_overlap_events_per_source: null,
  any_mismatch: null,
  diff_per_source: null,
  hub_outside_window_but_overlaps_sample: null,
  notes: [],
};

function overlapISO(start, end, wStart, wEnd) {
  if (!start || !wStart || !wEnd) return false;
  const e = end || start;
  return (start <= wEnd) && (e >= wStart);
}

if (Array.isArray(hubJson.events) && windowStart && windowEnd) {
  const hubOverlapPerSource = {};
  let hubOverlapTotal = 0;
  const outsideButOverlaps = [];

  for (const ev of hubJson.events) {
    const src = normalizeSource(ev?.Source || ev?.source);
    const { start, end } = getEventStartEndFromHub(ev);

    const isOverlap = overlapISO(start, end, windowStart, windowEnd);
    if (!isOverlap) continue;

    hubOverlapTotal++;
    hubOverlapPerSource[src] = (hubOverlapPerSource[src] || 0) + 1;

    // explain “Hub count bigger than date==... checks”
    const startOutside = (start < windowStart) || (start > windowEnd);
    if (startOutside) {
      outsideButOverlaps.push({
        source: src,
        Title: ev?.Title ?? null,
        Date: start ?? null,
        _EndDate: end ?? null,
        Link: ev?.Link ?? null,
      });
    }
  }

  sanity.hub_overlap_events_total = hubOverlapTotal;
  sanity.hub_overlap_events_per_source = hubOverlapPerSource;
  sanity.hub_outside_window_but_overlaps_sample = outsideButOverlaps.slice(0, 12);
  if (outsideButOverlaps.length > 0) {
    sanity.notes.push(
      `Hub returned ${outsideButOverlaps.length} overlapping events whose start Date is outside the window (likely long-running / in-progress).`
    );
  }
} else {
  sanity.notes.push('Hub events array missing OR window_start/window_end missing; cannot compute hub overlap sanity.');
}

// DB overlap counts (from node you should have added)
const dbOverlapRows = getAllJson('DB – Sanity overlap counts (s1)'); // safe if missing
if (dbOverlapRows.length > 0) {
  const dbPerSource = {};
  for (const r of dbOverlapRows) {
    const src = normalizeSource(r.source);
    dbPerSource[src] = {
      events_overlap: safeNum(r.events_overlap, 0),
      showtimes_overlap: safeNum(r.showtimes_overlap, 0),
      events_free: safeNum(r.events_free, 0),
      showtimes_free: safeNum(r.showtimes_free, 0),
    };
  }
  sanity.db_overlap_events_per_source = dbPerSource;
} else {
  sanity.notes.push('DB sanity node not present or returned no rows: "DB – Sanity overlap counts (s1)".');
}

// Compare hub vs db if both present
if (sanity.hub_overlap_events_per_source && sanity.db_overlap_events_per_source) {
  const diff = {};
  let any = false;

  const keys = new Set([
    ...Object.keys(sanity.hub_overlap_events_per_source),
    ...Object.keys(sanity.db_overlap_events_per_source),
  ]);

  for (const k of keys) {
    const hubCnt = safeNum(sanity.hub_overlap_events_per_source[k], 0);
    const dbCnt = safeNum(sanity.db_overlap_events_per_source[k]?.events_overlap, 0);
    const d = hubCnt - dbCnt;
    diff[k] = { hub_overlap_events: hubCnt, db_overlap_events: dbCnt, delta: d };
    if (d !== 0) any = true;
  }

  sanity.any_mismatch = any;
  sanity.diff_per_source = diff;

  if (any) {
    sanity.notes.push('Mismatch detected: hub overlap events != db overlap events (per source). Investigate dropped items or prune logic.');
  } else {
    sanity.notes.push('Sanity OK: hub overlap events match db overlap events (per source).');
  }
}

// -----------------------------
// Return summary
// -----------------------------
return [{
  json: {
    ran_at: new Date().toISOString(),
    config,
    hub,
    pipeline: {
      events_total: eventItems.length,
      events_distinct: eventIdSet.size,
      events_per_source: eventsPerSource,
      showtimes_total: showtimeRows.length,
      showtimes_distinct_in_run: showtimeKeySet.size,
      showtimes_timed: showtimesTimed,
      showtimes_no_time: showtimesNoTime,
      showtimes_per_source: showtimesPerSource,
    },
    db: {
      showtimes_to_prune: toPrune,
    },
    sanity,
  }
}];

// Mode: Run Once for All Items
const crypto = require('crypto');

function sha1(s) {
  return crypto.createHash('sha1').update(String(s)).digest('hex');
}

return items.map(item => {
  const j = item.json;

  const ref = (j.event_ref || '').trim();
  if (!ref) throw new Error('Missing event_ref in Hub output');

  const src = (j.source || '').trim();
  if (!src) throw new Error('Missing source in Hub output');

  // stable per-source logical event id (prevents cross-source collisions)
  j.event_id = sha1(`${src}|${ref}`);
  return item;
});

