WITH cfg AS (
  SELECT
    ('{{ $("Config – Window & Hub params1").first().json.date }}')::date AS window_start,
    ({{ $("Config – Window & Hub params1").first().json.days }})::int   AS days
)
SELECT public.s2_01a_apply(
  window_start,
  window_start + (days - 1)
) AS s2_01a_apply
FROM cfg;
